<?php
session_start();require_once '../conexion.php';if(!isset($_SESSION['usuario_id'])||$_SESSION['rol']!=='admin'){header('Location: ../login.php');exit;}$id=(int)($_GET['id']??0);$stmt=$conexion->prepare("SELECT * FROM Producto WHERE id_producto=?");$stmt->bind_param('i',$id);$stmt->execute();$producto=$stmt->get_result()->fetch_assoc();if(!$producto){header('Location: productos.php?error='.urlencode('Producto no encontrado.'));exit;}$error='';$categorias=$conexion->query("SELECT id_categoria,nombre FROM Categoria ORDER BY nombre");$ubicaciones=$conexion->query("SELECT id_ubicacion,pasillo,estante,posicion FROM Ubicacion ORDER BY pasillo,estante,posicion");if($_SERVER['REQUEST_METHOD']==='POST'){$nombre=trim($_POST['nombre']??'');$desc=trim($_POST['descripcion']??'');$stock=(int)($_POST['stock']??0);$min=(int)($_POST['stock_minimo']??0);$cat=(int)($_POST['id_categoria']??0);$ubi=(int)($_POST['id_ubicacion']??0);$estado=trim($_POST['estado_producto']??'Disponible');$stmt=$conexion->prepare("UPDATE Producto SET Nombre=?,descripcion=?,stock_actual=?,stock_minimo=?,estado_producto=?,id_categoria=?,id_ubicacion=? WHERE id_producto=?");$stmt->bind_param('ssiisiii',$nombre,$desc,$stock,$min,$estado,$cat,$ubi,$id);if($stmt->execute()){header('Location: productos.php?mensaje='.urlencode('Producto modificado correctamente.'));exit;}$error=$stmt->error;}
?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar producto</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../CSS/sistema.css"></head><body class="sistema-body"><main class="admin-container"><a href="productos.php" class="volver-link">← Volver</a><section class="dashboard-header"><h1>Editar producto</h1></section><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><div class="form-sistema-card"><form method="POST"><div class="mb-3"><label>Nombre</label><input name="nombre" class="form-control" value="<?=htmlspecialchars($producto['Nombre'])?>" required></div><div class="mb-3"><label>Descripción</label><input name="descripcion" class="form-control" value="<?=htmlspecialchars($producto['descripcion']??'')?>"></div><div class="mb-3"><label>Stock actual</label><input type="number" name="stock" min="0" class="form-control" value="<?=$producto['stock_actual']?>"></div><div class="mb-3"><label>Stock mínimo</label><input type="number" name="stock_minimo" min="0" class="form-control" value="<?=$producto['stock_minimo']?>"></div><div class="mb-3"><label>Estado</label><input name="estado_producto" class="form-control" value="<?=htmlspecialchars($producto['estado_producto'])?>"></div><div class="mb-3"><label>Categoría</label><select name="id_categoria" class="form-select"><?php while($x=$categorias->fetch_assoc()):?><option value="<?=$x['id_categoria']?>" <?=$x['id_categoria']==$producto['id_categoria']?'selected':''?>><?=htmlspecialchars($x['nombre'])?></option><?php endwhile;?></select></div><div class="mb-4"><label>Ubicación</label><select name="id_ubicacion" class="form-select"><?php while($x=$ubicaciones->fetch_assoc()):?><option value="<?=$x['id_ubicacion']?>" <?=$x['id_ubicacion']==$producto['id_ubicacion']?'selected':''?>><?=htmlspecialchars($x['pasillo'].'-'.$x['estante'].'-'.$x['posicion'])?></option><?php endwhile;?></select></div><button class="btn-picking">Guardar cambios</button></form></div></main></body></html>